// Weather, painted: a painting of your city in the weather and the light
// outside at this moment (Open-Meteo, no key), in a different style each time,
// painted again every few hours. Needs an OpenAI API key.
import { apiKey, paint, pictureFor, sizeFor, dayKey, pad } from './ai'

const STYLES: Record<string, string> = {
  woodblock: 'a Japanese woodblock print',
  impressionist: 'an Impressionist oil painting with visible brushstrokes',
  poster: 'a 1930s travel poster',
  watercolor: 'a quiet watercolor sketch',
  dutch: 'a Dutch Golden Age cityscape',
  linocut: 'a linocut in two colors',
  gouache: 'a gouache illustration from a children\'s book',
  realist: 'an American realist painting with long shadows',
  pixel: 'detailed pixel art',
  nouveau: 'an Art Nouveau poster',
}

const STYLE_NAMES: Record<string, string> = {
  woodblock: 'Japanese woodblock',
  impressionist: 'Impressionist oil',
  poster: '1930s travel poster',
  watercolor: 'Watercolor',
  dutch: 'Dutch Golden Age',
  linocut: 'Linocut',
  gouache: 'Picture-book gouache',
  realist: 'American realist',
  pixel: 'Pixel art',
  nouveau: 'Art Nouveau poster',
}

const WORDS: Record<number, string> = {
  0: 'a clear sky', 1: 'a mostly clear sky', 2: 'a few clouds', 3: 'a grey, overcast sky',
  45: 'fog', 48: 'freezing fog', 51: 'light drizzle', 53: 'drizzle', 55: 'heavy drizzle',
  61: 'light rain', 63: 'rain', 65: 'heavy rain', 66: 'freezing rain', 67: 'freezing rain',
  71: 'light snow falling', 73: 'snow falling', 75: 'heavy snow', 77: 'snow grains',
  80: 'rain showers', 81: 'rain showers', 82: 'violent rain showers', 85: 'snow showers', 86: 'heavy snow showers',
  95: 'a thunderstorm', 96: 'a thunderstorm with hail', 99: 'a thunderstorm with hail',
}

function lightAt(now: number, sunrise: number, sunset: number) {
  const minutes = (t: number) => (now - t) / 60000
  if (now < sunrise - 45 * 60000 || now > sunset + 45 * 60000) return 'night, with lit windows and street lamps'
  if (now < sunrise + 30 * 60000) return 'dawn, the first light'
  if (minutes(sunset) > -60 && now <= sunset) return 'golden hour, the sun low'
  if (now > sunset) return 'dusk, the blue hour'
  const hour = new Date(now).getHours()
  if (hour < 11) return 'morning'
  if (hour < 15) return 'midday'
  return 'afternoon'
}

function season(month: number, south: boolean) {
  const north = ['winter', 'winter', 'spring', 'spring', 'spring', 'summer', 'summer', 'summer', 'autumn', 'autumn', 'autumn', 'winter'][month]
  if (!south) return north
  return { winter: 'summer', spring: 'autumn', summer: 'winter', autumn: 'spring' }[north]
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const now = new Date()
  const every = Math.max(1, Math.min(24, Number(app.config.every) || 6))
  const slot = Math.floor(now.getHours() / every) * every
  const period = `${dayKey(now)}T${pad(slot)}`
  return pictureFor(app, 'painting', period, 'ai-scenes/weather-painted', (path) => {
    const key = apiKey()
    const query = String(app.config.location || 'Brussels').trim()
    const place = frameos.fetchJson('https://geocoding-api.open-meteo.com/v1/search?count=1&format=json&name=' + encodeURIComponent(query))
    const hit = place && place.results && place.results[0]
    if (!hit) throw new Error('Place not found: ' + query)
    const weather = frameos.fetchJson(
      `https://api.open-meteo.com/v1/forecast?latitude=${hit.latitude}&longitude=${hit.longitude}&timezone=auto&forecast_days=1` +
        '&current=temperature_2m,weather_code,wind_speed_10m,is_day&daily=sunrise,sunset&timeformat=unixtime',
    )
    const current = weather.current
    const words = WORDS[current.weather_code] || 'a changeable sky'
    const light = lightAt(now.getTime(), weather.daily.sunrise[0] * 1000, weather.daily.sunset[0] * 1000)
    const windy = current.wind_speed_10m > 30 ? ', a strong wind bending trees and flags' : ''
    const index = Math.floor(now.getTime() / (every * 3600000))
    const keys = Object.keys(STYLES)
    const styleKey = STYLES[String(app.config.style)] ? String(app.config.style) : keys[index % keys.length]
    const style = STYLES[styleKey]
    const prompt =
      `${style.charAt(0).toUpperCase() + style.slice(1)} of ${hit.name}, ${hit.country}, right now: ${light} in ${season(now.getMonth(), hit.latitude < 0)}, ` +
      `${words}${windy}, about ${Math.round(current.temperature_2m)} degrees Celsius. ` +
      `An everyday street or waterfront scene that people from ${hit.name} would recognise, its architecture and landmarks true to the place, ` +
      `small figures dressed for exactly this weather. The light, sky and ground must show this weather plainly. No text, signs with words, or logos.`
    const width = context.targetWidth || context.imageWidth || app.frame.width
    const height = context.targetHeight || context.imageHeight || app.frame.height
    const model = String(app.config.imageModel || 'gpt-image-2')
    paint(key, model, prompt, sizeFor(model, width, height, app.frame.embedded), path, app.frame.embedded)
    return {
      place: hit.name,
      words,
      temperature: Math.round(current.temperature_2m),
      style: STYLE_NAMES[styleKey],
      painted: `${pad(now.getHours())}:${pad(now.getMinutes())}`,
    }
  })
}

