// A small card over the painted weather: where, the weather it was painted
// in, and the style it was painted as.
import { readRecord } from './record'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const record = readRecord(app.state.painting)
  const text = record && record.text
  const u = Math.min(W, H) / 100
  const pad = Math.round(u * 4)
  const big = Math.round(u * 5.2)
  const small = Math.round(u * 2.7)

  const card = text ? (
    <div className={`flex flex-col bg-[#1c2230] rounded-[${Math.round(u * 1.6)}px] px-[${Math.round(u * 3)}px] py-[${Math.round(u * 2)}px]`}>
      <div className={`font-[FiraGO] font-semibold text-[${big}px] leading-none text-white`}>{`${text.place} · ${text.temperature}°`}</div>
      <div className={`font-[FiraGO] text-[${small}px] text-white/85 mt-[${Math.round(u * 1)}px]`}>
        {`${text.words.charAt(0).toUpperCase() + text.words.slice(1)}, painted at ${text.painted}`}
      </div>
      <div className={`font-[FiraGO] text-[${small}px] text-white/70`}>{`Painted as: ${text.style}`}</div>
    </div>
  ) : (
    <div className={`flex flex-col bg-[#1c2230] rounded-[${Math.round(u * 1.6)}px] px-[${Math.round(u * 3)}px] py-[${Math.round(u * 2)}px] max-w-[70%]`}>
      <div className={`font-[FiraGO] font-semibold text-[${big}px] text-white`}>The weather is being painted</div>
      <div className={`font-[FiraGO] text-[${small}px] text-white/85`}>
        {record && record.error ? record.error : 'Add an OpenAI API key in Settings.'}
      </div>
    </div>
  )
  // A round panel shows only the circle inside its square: the card goes
  // centred in the arc at the bottom, as wide as the circle is at its foot.
  if (context.round === true) {
    const d = Math.min(W, H)
    const foot = d * 0.36
    const width = Math.round(2 * Math.sqrt((d / 2) ** 2 - foot ** 2) - 24)
    const roundSmall = Math.max(14, Math.round(d * 0.03))
    return (
      <div className={`flex flex-col w-full h-full items-center justify-end pb-[${Math.round(H / 2 - foot)}px]`}>
        <div className={`flex flex-col items-center text-center w-[${width}px] bg-[#1c2230] rounded-[${Math.round(d * 0.04)}px] px-[${Math.round(d * 0.03)}px] py-[${Math.round(d * 0.022)}px]`}>
          {text ? (
            <>
              <div className={`font-[FiraGO] font-semibold text-[${Math.round(d * 0.055)}px] leading-none text-white`}>{`${text.place} · ${text.temperature}°`}</div>
              <div className={`font-[FiraGO] text-[${roundSmall}px] leading-snug text-white/85 mt-[${Math.round(d * 0.012)}px]`}>
                {`${text.words.charAt(0).toUpperCase() + text.words.slice(1)}, painted at ${text.painted}`}
              </div>
              <div className={`font-[FiraGO] text-[${roundSmall}px] text-white/70`}>{`Painted as: ${text.style}`}</div>
            </>
          ) : (
            <>
              <div className={`font-[FiraGO] font-semibold text-[${Math.round(d * 0.05)}px] text-white`}>The weather is being painted</div>
              <div className={`font-[FiraGO] text-[${roundSmall}px] text-white/85 line-clamp-3`}>
                {record && record.error ? record.error : 'Add an OpenAI API key in Settings.'}
              </div>
            </>
          )}
        </div>
      </div>
    )
  }
  return <div className={`flex w-full h-full items-end p-[${pad}px]`}>{card}</div>
}

